import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse(`{"title":"Démo complète et journal d'activité","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/demo-et-journal.md","filePath":"src/guide/admin/demo-et-journal.md"}`),n={name:"guide/admin/demo-et-journal.md"};function i(l,e,s,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="demo-complete-et-journal-d-activite" tabindex="-1">Démo complète et journal d&#39;activité <a class="header-anchor" href="#demo-complete-et-journal-d-activite" aria-label="Permalink to &quot;Démo complète et journal d&#39;activité&quot;">​</a></h1><p>Cette page regroupe deux fonctions d&#39;administrateur qui n&#39;ont aucun lien entre elles : activer une démonstration complète et gratuite d&#39;ERA, et consulter l&#39;historique des actions effectuées dans l&#39;application.</p><h2 id="activer-la-demo-complete" tabindex="-1">Activer la démo complète <a class="header-anchor" href="#activer-la-demo-complete" aria-label="Permalink to &quot;Activer la démo complète&quot;">​</a></h2><p><strong>Cette fonction n&#39;apparaît que si votre établissement est un tenant Era Admission encore en version gratuite</strong> — c&#39;est-à-dire un établissement qui utilise ERA uniquement pour gérer sa file de candidatures d&#39;admission, sans avoir encore souscrit de licence pour le reste de l&#39;application. Si votre établissement a déjà une licence active (ou est déjà en période de démo), vous ne verrez pas ce bouton.</p><p>Quand elle est disponible, l&#39;offre apparaît sur le <strong>Tableau de bord</strong> :</p><ol><li>Cliquez sur <strong>Activer la démo</strong>.</li><li>Une boîte de dialogue récapitule la durée (en jours) pendant laquelle tous les pôles d&#39;ERA seront débloqués sans engagement.</li><li>Cliquez sur <strong>Activer la démo</strong> pour confirmer.</li></ol><p>Une fois activée, une bannière sur le tableau de bord indique le nombre de jours restants, puis vous alerte quand la fin approche. Passé le délai, l&#39;accès repasse en lecture seule jusqu&#39;à l&#39;achat d&#39;une licence.</p><h2 id="consulter-le-journal-d-activite" tabindex="-1">Consulter le journal d&#39;activité <a class="header-anchor" href="#consulter-le-journal-d-activite" aria-label="Permalink to &quot;Consulter le journal d&#39;activité&quot;">​</a></h2><p><strong>Journal d&#39;activité</strong> (groupe <strong>Administration</strong> du menu) est un historique de qui a créé, modifié ou supprimé quoi dans l&#39;application, et quand.</p><p>Vous pouvez filtrer la liste par :</p><table tabindex="0"><thead><tr><th>Filtre</th><th>Détail</th></tr></thead><tbody><tr><td>Acteur</td><td>recherche par nom ou e-mail de la personne à l&#39;origine de l&#39;action</td></tr><tr><td>Entité</td><td>type d&#39;enregistrement concerné (élève, classe, paiement...)</td></tr><tr><td>Action</td><td>Créé, Modifié ou Supprimé</td></tr><tr><td>Date</td><td>une période « du » / « au »</td></tr></tbody></table><p>Cliquez sur <strong>Voir le détail</strong> sur une ligne pour afficher, dans une boîte de dialogue, le détail technique des champs modifiés par cette action.</p><p>Une limite importante à connaître : les changements de relations plusieurs-à-plusieurs (par exemple rattacher un tuteur à un élève, ou attribuer un rôle à un utilisateur) ne sont <strong>pas</strong> capturés dans ce journal — seules la création, la modification et la suppression directes d&#39;un enregistrement y apparaissent.</p>',13)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
